export const uid=()=>crypto.randomUUID();
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
export const currentMonth=()=>today().slice(0,7);
export function money(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((v||0)/100)}
export function cents(v){const n=Number(v);if(!Number.isFinite(n)||Math.abs(n)>1e10)throw Error('Informe um valor válido.');return Math.round(n*100)}
export function addMonth(month,n){const [y,m]=month.split('-').map(Number);const d=new Date(y,m-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
export function dateAt(month,day){const [y,m]=month.split('-').map(Number);const max=new Date(y,m,0).getDate();return `${month}-${String(Math.min(Number(day),max)).padStart(2,'0')}`}
export function addMonthsDate(date,n){const [y,m,d]=String(date).split('-').map(Number);const base=new Date(y,m-1+n,1);const last=new Date(base.getFullYear(),base.getMonth()+1,0).getDate();return `${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`}
export function investmentValue(i,asOf=today()){if(!i)return 0;if(i.yieldMode!=='fixed'||i.manualOverride)return i.current||0;const rate=Math.max(0,Number(i.annualRate)||0),events=Array.isArray(i.movements)&&i.movements.length?i.movements.filter(m=>m&&Number.isSafeInteger(m.amount)&&m.amount>0&&/^\d{4}-\d{2}-\d{2}$/.test(m.date)).sort((a,b)=>a.date.localeCompare(b.date)):[{type:'deposit',amount:Math.max(0,i.applied||0),date:String(i.appliedAt||i.updatedAt||asOf)}];if(!events.length)return 0;let value=0,cursor=events[0].date;for(const event of events){if(event.date>asOf)break;const days=Math.max(0,Math.floor((new Date(event.date+'T12:00:00')-new Date(cursor+'T12:00:00'))/86400000));value=Math.round(value*Math.pow(1+rate/100,days/365));value+=event.type==='withdrawal'?-event.amount:event.amount;value=Math.max(0,value);cursor=event.date}const days=Math.max(0,Math.floor((new Date(String(asOf)+'T12:00:00')-new Date(cursor+'T12:00:00'))/86400000));return Math.max(0,Math.round(value*Math.pow(1+rate/100,days/365)))}
export function investmentAppliedAt(i,asOf=today()){if(!i)return 0;const events=Array.isArray(i.movements)&&i.movements.length?i.movements.filter(m=>m&&Number.isSafeInteger(m.amount)&&m.amount>0&&/^\d{4}-\d{2}-\d{2}$/.test(m.date)).sort((a,b)=>a.date.localeCompare(b.date)):[{type:'deposit',amount:Math.max(0,i.applied||0),date:String(i.appliedAt||i.updatedAt||asOf)}];if(!events.length||events[0].date>asOf)return 0;return Math.max(0,events.filter(e=>e.date<=asOf).reduce((n,e)=>n+(e.type==='withdrawal'?-e.amount:e.amount),0))}
export function investmentYield(i,asOf=today()){if(!i)return 0;const value=investmentValue(i,asOf),applied=investmentAppliedAt(i,asOf),events=Array.isArray(i.movements)?i.movements:[],realized=events.filter(e=>e&&e.date<=asOf).reduce((n,e)=>n+(Number.isSafeInteger(e.realizedReturn)?e.realizedReturn:0),0);return value-applied+realized}
export function cardLimit(s,c,asOf=today()){if(!c)return 0;if(c.limitSource==='investment'){const i=(s.investments||[]).find(x=>x.id===c.limitInvestmentId);if(i){const available=Math.max(0,investmentValue(i,asOf)),configured=Number.isSafeInteger(c.guaranteeAmount)?Math.max(0,c.guaranteeAmount):0;return c.guaranteeFull===true||configured===0?available:Math.min(configured,available)}}return c.limit||0}
export function renewGoalDeadlines(s,from=today(),months=3){let changed=false;for(const g of s?.goals||[]){if(!g.focus||g.status!=='planned'||g.paidAt||!g.purchaseBy)continue;while(g.purchaseBy<=from){g.purchaseBy=addMonthsDate(g.purchaseBy,months);changed=true}}return changed}
const palettePresets={ocean:{name:'Oceano',accent:'#147d64',background:'#f4f6f9',nav:'#111c31',tint:'#e4f5ef'},lavender:{name:'Lavanda',accent:'#7357b8',background:'#f6f5fa',nav:'#211c38',tint:'#eeeafd'},sunset:{name:'Pôr do sol',accent:'#c15b45',background:'#fbf5f1',nav:'#34211d',tint:'#fbe9e4'},graphite:{name:'Grafite',accent:'#536477',background:'#f3f5f7',nav:'#17212b',tint:'#e9eef3'}};
export const palettes=palettePresets;
export function blank(){return {version:2,accounts:[],categories:[['Alimentação','expense'],['Assinaturas','expense'],['Compras pessoais','expense'],['Transporte','expense'],['Lazer','expense'],['Outros','both'],['Salário','income'],['Extra','income']].map(([name,type])=>({id:uid(),name,type})),transactions:[],cards:[],purchases:[],payments:[],recurring:[],goals:[],projects:[],investments:[],salary:{hours:0,minutes:0,rate:0,first:'R.I',second:'L.S',percent:50,ownerOnly:true},settings:{accent:'#147d64',palette:'ocean',theme:'light',density:'normal',widgets:['flow','accounts','recent','fixed'],fields:[],overview:{showInvestments:true,showAlerts:true,showGoals:true}}}}
export function migrate(s){if(!s||typeof s!=='object')return s;const n=structuredClone(s);const normalizeLabel=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();const carryoverLabel='sobrou do mes passado';const carryoverIds=new Set((n.categories||[]).filter(c=>normalizeLabel(typeof c==='string'?c:c.name)===carryoverLabel).map(c=>typeof c==='string'?'':c.id));n.transactions=(n.transactions||[]).filter(t=>!carryoverIds.has(t.categoryId)&&normalizeLabel(t.description)!==carryoverLabel);n.categories=(n.categories||[]).filter(c=>!carryoverIds.has(typeof c==='string'?'':c.id)&&normalizeLabel(typeof c==='string'?c:c.name)!==carryoverLabel);n.version=2;n.projects??=[];n.investments??=[];n.salary??={hours:0,minutes:0,rate:0,first:'R.I',second:'L.S',percent:50,ownerOnly:true};n.salary.ownerOnly=true;n.settings??={};n.settings.palette??='ocean';n.settings.theme=n.settings.theme==='dark'?'dark':'light';n.settings.overview??={showInvestments:true,showAlerts:true,showGoals:true};n.settings.overview={showInvestments:true,showAlerts:true,showGoals:true,...n.settings.overview};n.settings.widgets??=['flow','accounts','recent','fixed'];n.settings.fields??=[];n.settings.density??='normal';n.settings.accent??='#147d64';n.categories=(n.categories||[]).map(c=>typeof c==='string'?{id:uid(),name:c,type:'both'}:{...c,type:c.type||'both'});n.recurring=(n.recurring||[]).map(r=>{const schedule=r.schedule==='flexible'?'flexible':'due';return {...r,schedule,day:schedule==='flexible'?0:(Number.isInteger(r.day)&&r.day>=1&&r.day<=31?r.day:1),occurrences:schedule==='flexible'&&Number.isInteger(r.occurrences)&&r.occurrences>0?Math.min(31,r.occurrences):1}});n.investments=(n.investments||[]).map(i=>{const yieldMode='fixed',appliedAt=validDate(i.appliedAt)?i.appliedAt:(validDate(i.updatedAt)?i.updatedAt:today()),movements=Array.isArray(i.movements)?i.movements.map((m,j)=>({...m,id:m.id||`${i.id}:movement:${j}`,type:m.type==='withdrawal'?'withdrawal':'deposit',amount:Number.isSafeInteger(m.amount)?m.amount:Math.max(0,Math.round(Number(m.amount)||0)),realizedReturn:Number.isSafeInteger(m.realizedReturn)?m.realizedReturn:0,date:validDate(m.date)?m.date:appliedAt})).filter(m=>m.amount>0):((i.applied||0)>0?[{id:`${i.id}:initial`,type:'deposit',amount:i.applied,realizedReturn:0,date:appliedAt}]:[]);return {...i,accountId:i.accountId||'',sourceInvestmentId:i.sourceInvestmentId||'',purpose:i.purpose==='credit-guarantee'?'credit-guarantee':'general',linkedCardId:i.linkedCardId||'',guaranteePercent:Number.isFinite(Number(i.guaranteePercent))?Number(i.guaranteePercent):100,movements,yieldMode,annualRate:Number.isFinite(Number(i.annualRate))?Number(i.annualRate):0,appliedAt,manualOverride:i.manualOverride===true||i.yieldMode!=='fixed'}});const institutionKey=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/[-–—]/)[0].trim();n.investments.forEach(i=>{if(i.purpose==='credit-guarantee'&&i.linkedCardId&&i.accountId&&!i.sourceInvestmentId){const source=n.investments.find(x=>x.id!==i.id&&x.purpose==='general'&&x.applied>0&&x.appliedAt<=i.appliedAt&&institutionKey(x.institution)===institutionKey(i.institution));if(source){i.sourceInvestmentId=source.id;i.accountId=''}}});const redemptionTransactions=(n.transactions||[]).filter(t=>t.type==='income'&&!t.categoryId&&(/^Resgatar ·/.test(String(t.description||''))||/resgate do investimento/i.test(String(t.notes||''))));if(redemptionTransactions.length){let category=n.categories.find(c=>c.name==='Resgate de investimento'&&(c.type==='income'||c.type==='both'));if(!category){category={id:uid(),name:'Resgate de investimento',type:'income'};n.categories.push(category)}const categoryId=category.id;n.transactions=(n.transactions||[]).map(t=>redemptionTransactions.includes(t)?{...t,categoryId}:t)}n.transactions=(n.transactions||[]).map(t=>({...t,toInvestmentId:t.toInvestmentId||''}));n.cards=(n.cards||[]).map(c=>({...c,type:c.type||'credit',last4:String(c.last4||'').replace(/\D/g,'').slice(-4),limitSource:c.limitSource==='investment'?'investment':'manual',limitInvestmentId:c.limitInvestmentId||'',guaranteeAmount:Number.isSafeInteger(c.guaranteeAmount)?Math.max(0,c.guaranteeAmount):(c.limitSource==='investment'&&Number.isSafeInteger(c.limit)?Math.max(0,c.limit):0),guaranteeFull:c.limitSource==='investment'?(c.guaranteeFull===true||(!Number.isSafeInteger(c.guaranteeAmount)||c.guaranteeAmount===0)):false}));n.goals=(n.goals||[]).map(g=>{const {dueDate,...rest}=g;const status=g.status==='cancelled'?'cancelled':(g.status==='delivered'||g.status==='paid'||g.paidAt?'paid':'planned');return {...rest,projectId:g.projectId||'',status,paidAt:g.paidAt||'',paidTransactionId:g.paidTransactionId||'',purchaseBy:Boolean(g.focus)?(g.purchaseBy||dueDate||''):'',focus:Boolean(g.focus)}});return n}
export function installments(p){const base=Math.floor(p.amount/p.count),rem=p.amount%p.count;return Array.from({length:p.count},(_,i)=>({id:`${p.id}:${i}`,purchaseId:p.id,cardId:p.cardId,description:p.description,categoryId:p.categoryId,amount:base+(i<rem?1:0),month:addMonth(p.firstMonth,i),number:i+1,count:p.count,date:p.date}))}
export function invoice(s,cardId,month){const items=s.purchases.filter(p=>p.cardId===cardId).flatMap(installments).filter(i=>i.month===month);const total=items.reduce((a,x)=>a+x.amount,0);const paid=s.payments.filter(p=>p.cardId===cardId&&p.month===month).reduce((a,x)=>a+x.amount,0);return {items,total,paid,due:Math.max(0,total-paid)}}
export function accountBalance(s,id,through='9999-12-31'){const a=s.accounts.find(a=>a.id===id);let n=a&&a.openingDate<=through?a.opening:0;for(const t of s.transactions.filter(t=>t.date<=through)){const linkedInvestment=t.investmentMovementId&&s.investments?.some(i=>i.id===t.investmentId&&i.accountId===id&&!i.sourceInvestmentId);if(t.accountId===id&&!linkedInvestment)n+=t.type==='income'?t.amount:-t.amount;if(t.type==='transfer'&&t.toAccountId===id)n+=t.amount}for(const p of s.payments.filter(p=>p.date<=through&&p.accountId===id))n-=p.amount;for(const i of s.investments||[]){const start=i.appliedAt||i.updatedAt;if(i.accountId===id&&!i.sourceInvestmentId&&start<=through)n-=investmentValue(i,String(through)>today()?today():through)}return n}
export function outstanding(s,cardId,through='9999-12-31'){return s.purchases.filter(p=>p.cardId===cardId&&p.date<=through).reduce((n,p)=>n+p.amount,0)-s.payments.filter(p=>p.cardId===cardId&&p.date<=through).reduce((n,p)=>n+p.amount,0)}
export function investmentTotal(s,field='current',asOf=today()){return (s.investments||[]).reduce((n,i)=>n+(field==='current'?investmentValue(i,asOf):(i[field]||0)),0)}
export function summary(s,month){const end=dateAt(month,31);const assets=s.accounts.reduce((n,a)=>n+accountBalance(s,a.id,end),0)+investmentTotal(s,'current',today());const available=s.accounts.filter(a=>a.kind==='checking'||a.kind==='cash').reduce((n,a)=>n+accountBalance(s,a.id,end),0);const saved=assets-available;const debt=s.cards.reduce((n,c)=>n+outstanding(s,c.id,end),0);const ts=s.transactions.filter(t=>t.date.slice(0,7)===month);const income=ts.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0);const cashExpense=ts.filter(t=>t.type==='expense').reduce((n,t)=>n+t.amount,0);const creditExpense=s.purchases.flatMap(installments).filter(i=>i.month===month).reduce((n,i)=>n+i.amount,0);return {assets,available,saved,debt,net:assets-debt,income,expense:cashExpense+creditExpense,investments:investmentTotal(s,'current',today())}}
export function firstInvoice(date,card){const month=date.slice(0,7),day=Number(date.slice(8));return addMonth(month,(day>=card.closing?1:0)+(card.due<=card.closing?1:0))}
export function goalMonthly(g,from=today()){const remaining=Math.max(0,(g.target||0)-(g.saved||0));if(!remaining||!g.purchaseBy)return 0;const [sy,sm]=from.slice(0,7).split('-').map(Number),[ey,em]=g.purchaseBy.slice(0,7).split('-').map(Number);const months=Math.max(1,(ey-sy)*12+em-sm+1);return Math.ceil(remaining/months)}
export function salaryCalc(v){const total=Math.round((v.hours+v.minutes/60)*v.rate);const first=Math.round(total*v.percent/100);return {total,first,second:total-first}}
function validDate(v){if(typeof v!=='string'||!/^(\d{4})-(\d{2})-(\d{2})$/.test(v))return false;const d=new Date(v+'T12:00:00');return d.getFullYear()===+v.slice(0,4)&&d.getMonth()+1===+v.slice(5,7)&&d.getDate()===+v.slice(8)}
export function validate(input){const s=migrate(input);if(!s||s.version!==2)throw Error('Este arquivo não é um backup compatível.');for(const k of ['accounts','categories','transactions','cards','purchases','payments','recurring','goals','projects','investments'])if(!Array.isArray(s[k])||s[k].length>100000)throw Error('Dados inválidos: '+k);const ids=k=>new Set(s[k].map(x=>x.id)),ai=ids('accounts'),ci=ids('cards'),cat=ids('categories'),pi=ids('projects'),ii=ids('investments');const text=(v,n=500)=>typeof v==='string'&&v.length<=n,amount=v=>Number.isSafeInteger(v)&&Math.abs(v)<=1e12;
for(const k of ['accounts','categories','transactions','cards','purchases','payments','recurring','goals','projects','investments'])if(ids(k).size!==s[k].length||s[k].some(x=>!text(x.id,100)))throw Error('Identificadores inválidos.');
for(const a of s.accounts)if(!text(a.name)||!['checking','cash','saving','guarantee'].includes(a.kind)||!amount(a.opening)||!validDate(a.openingDate)||!/^#[0-9a-f]{6}$/i.test(a.color))throw Error('Conta inválida.');
for(const c of s.categories)if(!text(c.name)||!['expense','income','both'].includes(c.type))throw Error('Categoria inválida.');
for(const c of s.cards){const credit=c.type==='credit'||c.type==='both';if(!text(c.name)||!amount(c.limit)||c.limit<0||!['credit','debit','both'].includes(c.type)||!/^\d{0,4}$/.test(c.last4||'')||!['manual','investment'].includes(c.limitSource||'manual')||!amount(c.guaranteeAmount||0)||c.guaranteeAmount<0||typeof c.guaranteeFull!=='boolean'||(c.limitInvestmentId&&!ii.has(c.limitInvestmentId))||(credit&&!['closing','due'].every(k=>Number.isInteger(c[k])&&c[k]>=1&&c[k]<=31))||!/^#[0-9a-f]{6}$/i.test(c.color))throw Error('Cartão inválido.');}
for(const t of s.transactions)if(!['income','expense','transfer'].includes(t.type)||!text(t.description)||!amount(t.amount)||!validDate(t.date)||!ai.has(t.accountId)||(t.type==='transfer'&&!((ai.has(t.toAccountId)&&t.toAccountId!==t.accountId)||(ii.has(t.toInvestmentId)&&!t.toAccountId)))||(t.categoryId&&!cat.has(t.categoryId)))throw Error('Lançamento inválido.');
for(const p of s.purchases)if(!ci.has(p.cardId)||!['credit','both'].includes(s.cards.find(c=>c.id===p.cardId)?.type)||!text(p.description)||!amount(p.amount)||!Number.isInteger(p.count)||p.count<1||p.count>120||p.amount<p.count||!validDate(p.date)||!/^\d{4}-\d{2}$/.test(p.firstMonth)||(p.categoryId&&!cat.has(p.categoryId)))throw Error('Compra ou parcelamento inválido.');
for(const p of s.payments)if(!ci.has(p.cardId)||!ai.has(p.accountId)||!amount(p.amount)||!validDate(p.date)||!/^\d{4}-\d{2}$/.test(p.month))throw Error('Pagamento inválido.');
for(const c of s.cards)for(const m of new Set(s.payments.filter(p=>p.cardId===c.id).map(p=>p.month)))if(invoice(s,c.id,m).paid>invoice(s,c.id,m).total)throw Error('O pagamento não pode superar o total da fatura.');
for(const r of s.recurring)if(!text(r.name)||!amount(r.amount)||!['due','flexible'].includes(r.schedule||'due')||(r.schedule!=='flexible'&&(!Number.isInteger(r.day)||r.day<1||r.day>31))||(r.schedule==='flexible'&&(!Number.isInteger(r.occurrences)||r.occurrences<1||r.occurrences>31))||(r.accountId&&!ai.has(r.accountId))||(r.categoryId&&!cat.has(r.categoryId)))throw Error('Gasto fixo inválido.');
for(const p of s.projects)if(!text(p.name,100)||p.archived===undefined||typeof p.archived!=='boolean')throw Error('Projeto inválido.');
for(const g of s.goals)if(!text(g.name)||!amount(g.target)||!amount(g.saved)||g.saved<0||!['planned','paid','cancelled'].includes(g.status)||!['Ideia','Baixa','Média','Alta','Urgente'].includes(g.priority)||(g.projectId&&!pi.has(g.projectId))||(g.purchaseBy&&!validDate(g.purchaseBy))||typeof g.focus!=='boolean')throw Error('Objetivo inválido.');
for(const i of s.investments)if(!text(i.institution)||!text(i.name)||!text(i.type)||!amount(i.applied)||!amount(i.current)||i.applied<0||i.current<0||!validDate(i.updatedAt)||!validDate(i.appliedAt)||!['manual','fixed'].includes(i.yieldMode)||!Number.isFinite(i.annualRate)||i.annualRate<0||i.annualRate>1000||typeof i.manualOverride!=='boolean'||!['general','credit-guarantee'].includes(i.purpose||'general')||!text(i.linkedCardId||'',100)||!text(i.sourceInvestmentId||'',100)||(i.sourceInvestmentId&&!ii.has(i.sourceInvestmentId))||(i.sourceInvestmentId===i.id)||!Number.isFinite(Number(i.guaranteePercent??100))||Number(i.guaranteePercent??100)<0||Number(i.guaranteePercent??100)>1000||!Array.isArray(i.movements)||i.movements.length>10000||i.movements.some(m=>!text(m.id,100)||!['deposit','withdrawal'].includes(m.type)||!amount(m.amount)||m.amount<=0||!validDate(m.date)||(m.realizedReturn!==undefined&&(!Number.isSafeInteger(m.realizedReturn)||Math.abs(m.realizedReturn)>1e12)))||(i.accountId&&!ai.has(i.accountId))||(i.linkedCardId&&!ci.has(i.linkedCardId)))throw Error('Investimento inválido.');
const v=s.salary;if(!v||!Number.isFinite(v.hours)||v.hours<0||v.hours>10000||!Number.isInteger(v.minutes)||v.minutes<0||v.minutes>59||!amount(v.rate)||v.rate<0||!Number.isFinite(v.percent)||v.percent<0||v.percent>100||!text(v.first)||!text(v.second))throw Error('Divisão de salário inválida.');
if(!s.settings||!/^#[0-9a-f]{6}$/i.test(s.settings.accent)||!['light','dark'].includes(s.settings.theme)||!['normal','compact'].includes(s.settings.density)||!Array.isArray(s.settings.widgets)||s.settings.widgets.some(x=>!['flow','accounts','recent','fixed','investments','goals','alerts'].includes(x))||!Array.isArray(s.settings.fields)||s.settings.fields.some(f=>!text(f.id,100)||!text(f.name)||!['text','number','date'].includes(f.type)))throw Error('Preferências inválidas.');return s}
